def invert(node):
    if node is None:
        return None
    return TreeNode(node.val, invert(node.right), invert(node.left))

def is_same_tree(a, b):
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    return a.val == b.val and is_same_tree(a.left, b.left) and is_same_tree(a.right, b.right)

def is_symmetric_brute(root):
    if root is None:
        return True
    inverted_right = invert(root.right)                    # build a full inverted COPY
    return is_same_tree(root.left, inverted_right)

