bool isMirror(TreeNode* a, TreeNode* b) {
    if (!a && !b) return true;
    if (!a || !b) return false;
    return a->val == b->val
        && isMirror(a->left, b->right)                            // outer with outer
        && isMirror(a->right, b->left);                            // inner with inner
}

bool isSymmetric(TreeNode* root) {
    return !root || isMirror(root->left, root->right);
}
